{
  "title": "The Mirror Rescue of Ruined Aethos",
  "gate_token": "Q2TeDp1V1IKXZ05g6zxzpQ",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara the Cartographer traces the route to the ruined city.",
      "visual_description": "Mara stands before a cracked stone table, unrolling a parchment map under flickering torchlight, her brass compass glowing faintly.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Glass Diver swims through a broken window into the city's edge.",
      "visual_description": "A shattered stained-glass window reflects the Glass Diver's helmet as he emerges, coat shimmering with refracted light onto rubble.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp flickers a warning near the castle gates.",
      "visual_description": "The Oracle Lamp's single eye flares red in the shadow of massive iron gates, casting long, jagged shadows across the cobblestones.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "Mara and the Glass Diver meet beneath a torn royal banner.",
      "visual_description": "A faded banner with a tarnished crest flutters from a broken spire; Mara points upward while the Glass Diver adjusts his helmet.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The Tin Fox scampers ahead to scout the cursed tower.",
      "visual_description": "The small metal fox darts through a narrow alley, its blue glass eyes reflecting the twisted silhouette of a tower wrapped in thorns.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Mara deciphers a map riddle in the plaza of broken fountains.",
      "visual_description": "Water trickles from a shattered fountain as Mara traces ink lines with a stained finger, compass needle spinning slowly.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The Glass Diver faces a magic door that seals shut.",
      "visual_description": "A stone door inscribed with glowing runes slides closed; the Glass Diver presses his hand against it, ripples spreading like water.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The Oracle Lamp warns of an armored patrol approaching.",
      "visual_description": "The lamp's flame pulses urgently as metallic footsteps echo from a nearby archway; shadows of figures in plate armor grow larger.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "Mara hides behind a collapsed stall while the patrol passes.",
      "visual_description": "Mara crouches behind splintered wood, map clutched to her chest, as armored boots crunch on gravel just inches away.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The Tin Fox finds a key in a rusted birdcage.",
      "visual_description": "The metal fox nuzzles a small iron key lying inside a rusted cage, its tail ticking with a soft winding sound.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The Glass Diver retrieves the key from the fox and unlocks the magic door.",
      "visual_description": "The Glass Diver kneels, takes the key from the Tin Fox's mouth, and inserts it into a glowing lock; runes flicker and fade.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The Sleeping Tax Collector snores in a collapsed treasury.",
      "visual_description": "Amid scattered coins and ledgers, the Tax Collector sleeps using a thick book as a pillow, stamped papers stuck to his sleeve.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 13,
      "caption": "Mara shakes the Tax Collector awake for information.",
      "visual_description": "Mara pokes the Tax Collector's shoulder; he stirs, blinks, and a paper flutters from his forehead onto the dusty floor.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "The Oracle Lamp reveals a secret passage behind a tapestry.",
      "visual_description": "The lamp's light shines through a moth-eaten tapestry, illuminating a hidden stone archway that was previously invisible.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The team descends into a crypt filled with whispering echoes.",
      "visual_description": "Mara, Glass Diver, Tin Fox, and Oracle Lamp move single file down slick stairs, echoes of old voices bouncing off bone-white walls.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "The Glass Diver opens a final portal through a cracked mirror.",
      "visual_description": "Standing before a tall cracked mirror, the Glass Diver presses his palm against the glass; the surface ripples and reveals a courtyard beyond.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "The escape begins across a crumbling stone bridge.",
      "visual_description": "The group dashes onto a narrow bridge with missing stones, mist rising from a chasm below; the Tin Fox leads, tail spinning.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them as they reach safety.",
      "visual_description": "The last stone falls away as the party jumps onto solid ground; the ruined city looms beyond the shattered bridge, dust settling.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

